B.a9L=s(["1 Dose Thunfisch im eigenen Saft (ohne Salz/Oel abgegossen)","1 Ei","4-5 EL Haferflocken oder Reismehl"],t.s)
B.a7v=s(["Backofen auf 175 Grad C vorheizen.","Alles zu einer Masse verruehren.","Duenn auf ein Backblech streichen.","15 Minuten backen, abkuehlen, in kleine Wuerfel schneiden."],t.s)
B.awF=new A.hE(B.jF,"Thunfisch-Wuerfel","Herzhaft und sehr beliebt",B.a9L,B.a7v,"Im Kuehlschrank 3-4 Tage, einfrieren moeglich.","Perfekt als hochwertiges Trainings-Leckerli.")
B.aaj=s(["150 g Kuerbispuree (ungesuesst, ohne Gewuerze)","200 g Vollkornmehl oder Haferflocken","1 Ei"],t.s)
B.a5r=s(["Backofen auf 180 Grad C vorheizen.","Zutaten zu einem Teig verkneten, ggf. etwas Mehl ergaenzen.","Ausrollen und Formen ausstechen.","20 Minuten backen, bis sie knusprig sind."],t.s)
B.awD=new A.hE(B.jF,"Kuerbis-Kekse","Gut fuer die Verdauung",B.aaj,B.a5r,"Trocken gelagert 1-2 Wochen.",null)
B.acJ=s(["1 geraspelte Karotte","1/2 geraspelter Apfel (ohne Kerngehaeuse)","150 g Haferflocken","1 Ei"],t.s)
B.aa0=s(["Backofen auf 180 Grad C vorheizen.","Alles vermengen, kleine Taler formen.","18-20 Minuten backen, auskuehlen lassen."],t.s)
B.awH=new A.hE(B.jF,"Karotten-Apfel-Taler","Vitaminreich",B.acJ,B.aa0,"In einer Dose ca. 1 Woche.",null)
B.aay=s(["3 EL Magerquark","frische Petersilie, fein gehackt","Haferflocken zum Binden"],t.s)
B.a5w=s(["Quark mit Petersilie verruehren.","So viele Haferflocken einkneten, bis eine formbare Masse entsteht.","Kleine Baellchen rollen."],t.s)
B.awC=new A.hE(B.tg,"Quark-Kraeuter-Baellchen","In 5 Minuten fertig",B.aay,B.a5w,"Im Kuehlschrank 2-3 Tage.","Petersilie hilft sogar gegen Mundgeruch.")
B.a6X=s(["2 EL Erdnussbutter (OHNE Xylit/Suessstoff, ungesalzen)","Haferflocken"],t.s)
B.a9k=s(["Erdnussbutter mit so vielen Haferflocken verkneten, bis es formbar ist.","Kleine Kugeln rollen und kurz kalt stellen."],t.s)
B.awA=new A.hE(B.tg,"Erdnussbutter-Happen","Nur 2 Zutaten",B.a6X,B.a9k,"Im Kuehlschrank ca. 4 Tage.","WICHTIG: Erdnussbutter MUSS xylitfrei sein - Xylit ist giftig.")
B.a64=s(["Naturjoghurt (ohne Zucker)","einige Heidelbeeren oder Himbeeren"],t.s)
B.adJ=s(["Joghurt mit den Beeren verruehren.","In eine Eiswuerfelform oder Silikonform fuellen.","Ueber Nacht einfrieren."],t.s)
